const KEY_OK = /^[a-z0-9_-]{1,24}$/;
const room = (env, k) => env.ROOMS.get(env.ROOMS.idFromName('draft:' + k));
/** /api/draft lewat DraftRoom: GET ?k= isi draft, GET ?ks=a,b daftar draft tim (template yang dikenal halaman), POST simpan. */
async function roomApi(request, env, who) {
  const u = new URL(request.url), xw = { 'x-who': encodeURIComponent(who) };
  if (request.method === 'GET') {
    const k = u.searchParams.get('k');
    if (k) return KEY_OK.test(k) ? room(env, k).fetch(`https://room/get?k=${k}`, { headers: xw }) : json({ error: 'k?' }, 400);
    const ks = (u.searchParams.get('ks') || '').split(',').filter((x) => KEY_OK.test(x)).slice(0, 30);
    if (!ks.length) return draftApi(request, env, who);   // halaman versi lama: daftar dari KV
    const L = await Promise.all(ks.map((x) => room(env, x).fetch(`https://room/meta?k=${x}`, { headers: xw }).then((r) => r.json()).catch(() => null)));
    return json(L.filter((x) => x && x.at));
  }
  if (request.method !== 'POST') return json({ error: 'method' }, 405);
  if (request.headers.get('origin') && request.headers.get('origin') !== u.origin) return json({ error: 'origin' }, 403);
  const text = await request.text(), b = (() => { try { return JSON.parse(text); } catch (e) { return {}; } })(), k = String(b.k || '');
  if (!KEY_OK.test(k) || !b.data || typeof b.data !== 'object') return json({ error: 'Data draft tidak valid' }, 400);
  if (text.length > ROOM_MAX) return json({ error: 'Draft terlalu besar' }, 413);
  return room(env, k).fetch(`https://room/put?k=${k}`, { method: 'POST', headers: { ...xw, 'content-type': 'application/json' }, body: text });
}
/** /api/draft/ws?k= : WebSocket ke DraftRoom template itu (hanya dari halaman ini sendiri; cookie sesi ikut terkirim). */
function roomSocket(request, env, who) {
  const u = new URL(request.url), k = u.searchParams.get('k') || '';
  if (!env.ROOMS) return json({ error: 'Draft realtime belum dipasang (Durable Object ROOMS).', off: true }, 501);
  if (request.headers.get('upgrade') !== 'websocket') return json({ error: 'WebSocket?' }, 426);
  if (request.headers.get('origin') !== u.origin) return json({ error: 'origin' }, 403);
  if (!KEY_OK.test(k)) return json({ error: 'k?' }, 400);
  const r = new Request(`https://room/ws?k=${k}`, request);
  r.headers.set('x-who', encodeURIComponent(who));
  return room(env, k).fetch(r);
}

export default {
  async fetch(request, env = {}) {
    const me = await hubUser(request, env);
    if (me instanceof Response) return me;
    const path = new URL(request.url).pathname, hub = env.HUB_URL || HUB, who = me.n || me.e || 'tim';
    if (path === '/api/draft/ws') return roomSocket(request, env, who);
    if (path === '/api/draft') return env.ROOMS ? roomApi(request, env, who) : draftApi(request, env, who);
    if (path === '/api/market') {
      try { return json(await market()); } catch (e) { return json({ error: msg(e) }, 502); }
    }
    const name = esc(title(env, 'Email Studio'));
    return new Response(HTML.replace('<head>', () => '<head>' + profileScript(env) + themeHead(EMAIL_THEME_CSS)).replace('<title>Email Studio</title>', () => `<title>${name}</title>`).replace('<b>Email Studio</b>', () => `<b>${name}</b>`).replace('<!--USERBAR-->', () => `<script>if(window.top===window.self)location.replace(${JSON.stringify(hub + '/#' + APP)})</script>`)   /* hanya dipakai di dalam dashboard: dibuka langsung -> pindah ke tab-nya di Tool Hub. Email & Keluar ada di bilah dashboard */, { headers: { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'private, no-store', 'content-security-policy': `frame-ancestors 'self' ${hub}` } });   // hanya boleh dibingkai oleh Tool Hub
  },
};